function checkTelemetry(itemToAdd) {
  if (itemToAdd) {
    expectedTelemetryValue[itemToAdd] = 1;
    Assert.deepEqual(
      Glean.calendar.viewInitialized.testGetValue(),
      expectedTelemetryValue,
      `${itemToAdd} should have been recorded`
    );
  } else {
    Assert.deepEqual(
      Glean.calendar.viewInitialized.testGetValue(),
      expectedTelemetryValue,
      "no changes expected"
    );
  }
}

add_setup(async function () {
  // Mochitests can begin before delayed startup has finished loading Calendar.
  // Wait for its deactivator to be ready before enabling the test calendar.
  await window.delayedStartupPromise;

  // No views should have been initialized at the start of the test.
  checkTelemetry();

  cal.manager.getCalendars()[0].setProperty("disabled", false);
  checkTelemetry("agenda");
});

